//! `DatePeriod` against PHP 8.5.13 (`tests/vectors/period.json`, generated by `period.gen.php`; regenerate with
//! `crates/twig-date/tests/vectors/regen.sh period`).

mod common;

use common::*;
use serde_json::Value as Json;
use twig_date::{DateObject, DatePeriodObject, IntervalObject, classes};
use twig_value::object::{CallArgs, FetchMode, PropertyCheck};
use twig_value::{ObjectRef, Value, convert, dump};

fn make_date(c: &Ctx, d: &Json) -> Value {
    let (kind, arg) = (s(&d[0]), s(&d[1]));
    Value::Object(match kind {
        "dti" => DateObject::construct(&c.ctx, classes::datetime_immutable(), arg.as_bytes(), None)
            .unwrap(),
        "iv" => IntervalObject::construct(&c.ctx, arg.as_bytes()).unwrap(),
        _ => DateObject::construct(&c.ctx, classes::datetime(), arg.as_bytes(), None).unwrap(),
    })
}

fn scalar(v: &Json) -> Value {
    match v {
        Json::Number(n) => Value::Int(n.as_i64().unwrap()),
        Json::String(s) => Value::from(s.as_str()),
        other => panic!("scalar {other}"),
    }
}

/// A prototype period whose `__construct` / `createFromISO8601String` methods the test calls.
fn proto(c: &Ctx) -> ObjectRef {
    let start = make_date(c, &serde_json::json!(["dt", "2000-01-01"]));
    let iv = IntervalObject::construct(&c.ctx, b"P1D").unwrap();
    DatePeriodObject::with_recurrences(&c.ctx, start.as_object().unwrap(), &iv, 1, 0).unwrap()
}

fn build(c: &Ctx, kind: &str, a: &Json) -> Result<ObjectRef, twig_value::PhpError> {
    let mut diags: Vec<twig_value::Diagnostic> = Vec::new();
    let r = match kind {
        "rec" | "end" => {
            let start = make_date(c, &a[0]);
            let iv = IntervalObject::construct(&c.ctx, s(&a[1]).as_bytes()).unwrap();
            if kind == "rec" {
                DatePeriodObject::with_recurrences(
                    &c.ctx,
                    start.as_object().unwrap(),
                    &iv,
                    i(&a[2]),
                    i(&a[3]),
                )
            } else {
                let end = make_date(c, &a[2]);
                DatePeriodObject::with_end(
                    &c.ctx,
                    start.as_object().unwrap(),
                    &iv,
                    end.as_object().unwrap(),
                    i(&a[3]),
                )
            }
        }
        "create" => {
            DatePeriodObject::create_from_iso8601_string(&c.ctx, s(&a[0]).as_bytes(), i(&a[1]))
        }
        _ => {
            // new DatePeriod(...$args): run __construct on a fresh object.
            let args: Vec<Value> = a
                .as_array()
                .unwrap()
                .iter()
                .map(|x| {
                    if x.is_array() {
                        make_date(c, x)
                    } else {
                        scalar(x)
                    }
                })
                .collect();
            let p = DatePeriodObject::new_uninitialized(&c.ctx, classes::dateperiod());
            let p = ObjectRef::new(p);
            p.call_method("__construct", CallArgs::from(args), &mut diags)
                .map(|_| p)
        }
    };
    assert!(diags.is_empty() || kind == "iso" || kind == "raw");
    r
}

fn enc_value(v: &Value) -> Json {
    match v {
        Value::Object(o) if o.instance_of("DateTimeInterface") => {
            serde_json::json!({"$class": o.class_name(), "show": show(o)})
        }
        Value::Object(o) if o.instance_of("DateInterval") => {
            let f = call(
                o,
                "format",
                vec![php_str("%y %m %d %h %i %s %f %R %a")],
                &mut Vec::new(),
            )
            .unwrap();
            serde_json::json!({"$class": "DateInterval", "fmt": str_val(&f)})
        }
        Value::Array(a) => {
            if a.is_list() {
                Json::Array(a.values().map(enc_value).collect())
            } else {
                let mut m = serde_json::Map::new();
                for (k, x) in a.iter() {
                    m.insert(enc(k.to_php_string().as_bytes()), enc_value(x));
                }
                Json::Object(m)
            }
        }
        other => to_json(other),
    }
}

fn normalize_handles(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    let b = text.as_bytes();
    let mut k = 0;
    while k < b.len() {
        if b[k] == b'#' && k > 0 && b[k - 1] == b')' {
            let mut j = k + 1;
            while j < b.len() && b[j].is_ascii_digit() {
                j += 1;
            }
            if j > k + 1 && text[j..].starts_with(" (") {
                out.push_str("#N");
                k = j;
                continue;
            }
        }
        out.push(b[k] as char);
        k += 1;
    }
    out
}

#[test]
fn periods() {
    let v = load("period");
    let c = Ctx::new();
    c.now(1_700_000_000, 123_456);
    assert!(
        c.ctx
            .default_timezone_set(b"Europe/Vilnius", &mut Vec::new())
            .unwrap()
    );
    let mut r = Report::new("DatePeriod");
    for case in v["periods"].as_array().unwrap() {
        let (kind, a) = (s(&case[1][0]), &case[1][1]);
        let mut diags = Vec::new();
        let p = if kind == "iso" {
            let args = vec![scalar(&a[0]), scalar(&a[1])];
            let p = ObjectRef::new(DatePeriodObject::new_uninitialized(
                &c.ctx,
                classes::dateperiod(),
            ));
            p.call_method("__construct", CallArgs::from(args), &mut diags)
                .map(|_| p)
        } else if kind == "raw" {
            let args: Vec<Value> = a
                .as_array()
                .unwrap()
                .iter()
                .map(|x| {
                    if x.is_array() {
                        make_date(&c, x)
                    } else {
                        scalar(x)
                    }
                })
                .collect();
            let p = ObjectRef::new(DatePeriodObject::new_uninitialized(
                &c.ctx,
                classes::dateperiod(),
            ));
            p.call_method("__construct", CallArgs::from(args), &mut diags)
                .map(|_| p)
        } else {
            build(&c, kind, a)
        };
        let what = || format!("{} {}", case[0], case[1]);
        let p = match p {
            Ok(p) => p,
            Err(e) => {
                r.eq(Json::String(exc(&e)), case[2].clone(), what);
                r.eq(Json::from(diag_strings(&diags)), case[6].clone(), || {
                    format!("diagnostics {}", what())
                });
                continue;
            }
        };
        // properties before iterating
        let mut before = serde_json::Map::new();
        for n in [
            "start",
            "current",
            "end",
            "interval",
            "recurrences",
            "include_start_date",
            "include_end_date",
        ] {
            let val = p
                .read_property(n.as_bytes(), FetchMode::Read, &mut diags)
                .unwrap();
            let isset = p
                .has_property(n.as_bytes(), PropertyCheck::Isset, &mut diags)
                .unwrap();
            let exists = p.property_exists(n.as_bytes(), &mut diags).unwrap();
            before.insert(
                n.to_owned(),
                Json::Array(vec![enc_value(&val), Json::Bool(isset), Json::Bool(exists)]),
            );
        }
        // foreach
        let mut it = Vec::new();
        let mut iter = p.get_iterator(&mut diags).unwrap().unwrap();
        let mut iteration = iter.rewind(&mut diags).map(|_| ());
        let mut n = 0;
        while iteration.is_ok() {
            match iter.valid(&mut diags) {
                Ok(true) => {}
                Ok(false) => break,
                Err(e) => {
                    iteration = Err(e);
                    break;
                }
            }
            let d = iter.current(&mut diags).unwrap();
            let k = iter.key(&mut diags).unwrap();
            let d = obj(d);
            it.push(serde_json::json!([to_json(&k), d.class_name(), show(&d)]));
            n += 1;
            if n > 10 {
                break;
            }
            iter.next(&mut diags).unwrap();
        }
        let it = match iteration {
            Ok(()) => Json::Array(it),
            Err(e) => Json::String(exc(&e)),
        };
        r.eq(it, case[2].clone(), || format!("iteration {}", what()));
        // getters
        let mut getters = serde_json::Map::new();
        for m in [
            "getStartDate",
            "getEndDate",
            "getDateInterval",
            "getRecurrences",
        ] {
            let g = match call(&p, m, vec![], &mut diags) {
                Ok(v) => enc_value(&v),
                Err(e) => Json::String(exc(&e)),
            };
            getters.insert(m.to_owned(), g);
        }
        r.eq(Json::Object(getters), case[3].clone(), || {
            format!("getters {}", what())
        });
        // property operations
        let mut props = serde_json::Map::new();
        props.insert("before".to_owned(), Json::Object(before));
        let cur = p
            .read_property(b"current", FetchMode::Read, &mut diags)
            .unwrap();
        props.insert("current_after".to_owned(), enc_value(&cur));
        let res = |x: Result<(), twig_value::PhpError>| match x {
            Ok(()) => Json::String("ok".to_owned()),
            Err(e) => Json::String(exc(&e)),
        };
        props.insert(
            "write".to_owned(),
            res(p.write_property(b"start", Value::Null, &mut diags)),
        );
        props.insert(
            "unset".to_owned(),
            res(p.unset_property(b"recurrences", &mut diags)),
        );
        props.insert(
            "dyn".to_owned(),
            res(p.write_property(b"foo", Value::Int(1), &mut diags)),
        );
        r.eq(Json::Object(props), case[4].clone(), || {
            format!("properties {}", what())
        });
        // getIterator()
        let ii = obj(call(&p, "getIterator", vec![], &mut diags).unwrap());
        let mut iterj = vec![Json::String(ii.class_name().to_owned())];
        for _ in 0..3 {
            let valid = call(&ii, "valid", vec![], &mut diags).unwrap();
            let key = call(&ii, "key", vec![], &mut diags).unwrap();
            let cur = if valid == Value::Bool(true) {
                Json::String(show(
                    &obj(call(&ii, "current", vec![], &mut diags).unwrap()),
                ))
            } else {
                Json::Null
            };
            iterj.push(Json::Array(vec![to_json(&valid), to_json(&key), cur]));
            call(&ii, "next", vec![], &mut diags).unwrap();
        }
        call(&ii, "rewind", vec![], &mut diags).unwrap();
        let valid = call(&ii, "valid", vec![], &mut diags).unwrap();
        let key = call(&ii, "key", vec![], &mut diags).unwrap();
        iterj.push(Json::Array(vec![to_json(&valid), to_json(&key)]));
        // dumps
        let val = Value::Object(p.clone());
        let vd = dump::var_dump(&val, &mut diags).unwrap();
        let js = twig_value::builtins::format::json_encode(&val, None, None, &mut diags).unwrap();
        let arr = convert::to_array(&val, &mut diags).unwrap();
        let ser = call(&p, "__serialize", vec![], &mut diags).unwrap();
        let dumps = Json::Array(vec![
            Json::String(normalize_handles(&enc(vd.as_bytes()))),
            to_json(&js),
            enc_value(&Value::Array(arr)),
            enc_value(&ser),
            Json::Array(iterj),
        ]);
        r.eq(dumps, case[5].clone(), || format!("dumps {}", what()));
        r.eq(Json::from(diag_strings(&diags)), case[6].clone(), || {
            format!("diagnostics {}", what())
        });
    }
    r.finish();
}

#[test]
fn set_state_and_unserialize() {
    let v = load("period");
    let c = Ctx::new();
    c.now(1_700_000_000, 123_456);
    assert!(
        c.ctx
            .default_timezone_set(b"Europe/Vilnius", &mut Vec::new())
            .unwrap()
    );
    let mut r = Report::new("DatePeriod::__set_state()/__unserialize()");
    // The generator's base: (new DatePeriod(new DateTime('2024-01-01'), new DateInterval('P1D'), 2))->__serialize().
    let start = make_date(&c, &serde_json::json!(["dt", "2024-01-01"]));
    let iv = IntervalObject::construct(&c.ctx, b"P1D").unwrap();
    let base_p =
        DatePeriodObject::with_recurrences(&c.ctx, start.as_object().unwrap(), &iv, 2, 0).unwrap();
    let base = match call(&base_p, "__serialize", vec![], &mut Vec::new()).unwrap() {
        Value::Array(a) => a,
        _ => unreachable!(),
    };
    for case in v["state"].as_array().unwrap() {
        let name = s(&case[0]);
        let mut data = base.clone();
        match name {
            "valid" => {}
            "no_start" => {
                data.remove(&"start".into());
            }
            "null_start" => {
                data.insert("start", Value::Null);
            }
            "bad_interval" => {
                data.insert("interval", Value::from("P1D"));
            }
            "big_recurrences" => {
                data.insert("recurrences", Value::Int(2_147_483_648));
            }
            "string_recurrences" => {
                data.insert("recurrences", Value::from("3"));
            }
            "int_include" => {
                data.insert("include_start_date", Value::Int(1));
            }
            "extra" => {
                data.insert("extra", Value::from("x"));
            }
            other => panic!("state {other}"),
        }
        let mut diags = Vec::new();
        let p = proto(&c);
        let r1 = match call(
            &p,
            "__set_state",
            vec![Value::Array(data.clone())],
            &mut diags,
        ) {
            Ok(o) => enc_value(&Value::Array(convert::to_array(&o, &mut diags).unwrap())),
            Err(e) => Json::String(exc(&e)),
        };
        let start = make_date(&c, &serde_json::json!(["dt", "2000-01-01"]));
        let iv = IntervalObject::construct(&c.ctx, b"PT1H").unwrap();
        let p2 = DatePeriodObject::with_recurrences(&c.ctx, start.as_object().unwrap(), &iv, 1, 0)
            .unwrap();
        let r2 = match call(&p2, "__unserialize", vec![Value::Array(data)], &mut diags) {
            Ok(_) => enc_value(&Value::Array(
                convert::to_array(&Value::Object(p2.clone()), &mut diags).unwrap(),
            )),
            Err(e) => Json::String(exc(&e)),
        };
        r.eq(r1, case[1].clone(), || format!("__set_state {name}"));
        r.eq(r2, case[2].clone(), || format!("__unserialize {name}"));
        r.eq(Json::from(diag_strings(&diags)), case[3].clone(), || {
            format!("diagnostics {name}")
        });
    }
    r.finish();
}
